scripts.server:
num n = 0;
public action onPlayerSpawn(str id) {
    obj p = GAME.PLAYERS.findByID(id);
    n += 1;
    if (n == 1) { return; }
    num k = n - 2;
    p.position.x = -15 + k * 10;
    p.position.z = 0;
    p.position.y = 0;
    p.rotation.x = 3.14159;
    if (k == 0) { p.pose = {hold: 1}; }
    if (k == 1) { p.pose = {holdL: 1}; }
    if (k == 2) { p.pose = {legs: 2, legX: -1.5, bodyY: -2.5, weapon: 0, armL: num[-0.9, 0, 0], armR: num[-0.9, 0, 0]}; }
    if (k == 3) { p.pose = {legs: 0, bodyY: -5, armL: num[0.6, 0, 0.9], armR: num[0.6, 0, -0.9], torsoX: -0.3}; }
    if (k > 3) { p.position.z = -60; }
}

scripts.client:
num done = 0;
public action update(num delta) {
    if (done > 0) { return; }
    obj[] ps = GAME.PLAYERS.list();
    if (lengthOf ps < 5) { return; }
    for (num i = 0; i < lengthOf ps; i++) {
        obj p = ps[i];
        obj c = GAME.SCENE.addCube("", "#ff2222", 0, 0, 0, 1.4, 1.4, 1.4);
        c.attachTo(p, 0, 0, 0, false, "handL");
        obj h = GAME.SCENE.addCube("", "#22ccff", 0, -1, 0, 2.4, 2.4, 2.4);
        h.attachTo(p, 0, 0, 0, false, "hands");
    }
    done = 1;
    GAME.log("attached", toStr lengthOf ps);
}
